-- A Know mark applies only to the direction it was marked in (D-028): the primary key becomes
-- (user_id, item_id, known_target). SQLite can't change a primary key in place, so the table is
-- rebuilt. Generated by drizzle-kit, then edited by hand:
-- - WITHOUT ROWID is kept (D-010; test/schema.test.ts asserts it).
-- - No PRAGMA foreign_keys lines: D1 always enforces foreign keys, and no table refers to
--   user_known_items, so dropping it removes nothing else.
-- Every existing mark is copied as is: it stays known in the direction it was marked in.
CREATE TABLE `__new_user_known_items` (
	`user_id` text NOT NULL,
	`item_id` integer NOT NULL,
	`known_target` text NOT NULL,
	`known_in_cycle` integer NOT NULL,
	`known_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `item_id`, `known_target`),
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`item_id`) REFERENCES `items`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "ck_known_cycle" CHECK(known_in_cycle >= 1)
) WITHOUT ROWID;
